create table if not exists users (id text primary key, email text not null unique, password_hash text not null, role text not null, name text not null, email_verified_at timestamptz, onboarding_completed boolean not null default false, created_at timestamptz not null default now());
create table if not exists profiles (user_id text primary key references users(id) on delete cascade, desk text not null default 'macro', timezone text not null default 'UTC', region text not null default 'Global', density text not null default 'dense', bio text not null default '', subscription_plan text not null default 'pro');
create table if not exists sessions (id text primary key, user_id text not null references users(id) on delete cascade, token_hash text not null unique, user_agent text not null default '', ip_address text not null default '', expires_at timestamptz not null, revoked_at timestamptz, created_at timestamptz not null default now());
create table if not exists email_verification_tokens (id text primary key, user_id text not null references users(id) on delete cascade, token_hash text not null unique, expires_at timestamptz not null, consumed_at timestamptz, created_at timestamptz not null default now());
create table if not exists password_reset_tokens (id text primary key, user_id text not null references users(id) on delete cascade, token_hash text not null unique, expires_at timestamptz not null, consumed_at timestamptz, created_at timestamptz not null default now());
create table if not exists assets (id text primary key, symbol text not null unique, name text not null, class_name text not null, region text not null, description text not null default '');
create table if not exists event_families (id text primary key, slug text not null unique, name text not null, category text not null, country text not null, currency text not null, importance text not null, description text not null, why_it_matters text not null);
create table if not exists events (id text primary key, family_id text not null references event_families(id) on delete cascade, slug text not null unique, title text not null, status text not null, scheduled_at timestamptz not null, previous_value numeric(12,4), forecast_value numeric(12,4), actual_value numeric(12,4), surprise_pct numeric(12,4), why_it_matters text not null, narrative text not null default '');
create table if not exists event_release_assets (event_id text not null references events(id) on delete cascade, asset_id text not null references assets(id) on delete cascade, primary key (event_id, asset_id));
create table if not exists event_reaction_windows (id text primary key, event_id text not null references events(id) on delete cascade, reaction_window text not null, avg_move_pct numeric(12,4) not null, consistency numeric(12,4) not null, narrative text not null);
create table if not exists regime_snapshots (id text primary key, label text not null, score numeric(12,4) not null, confidence numeric(12,4) not null, trend text not null, interpretation text not null, methodology text not null, created_at timestamptz not null default now());
create table if not exists regime_components (id text primary key, snapshot_id text not null references regime_snapshots(id) on delete cascade, key text not null, label text not null, value numeric(12,4) not null);
create table if not exists market_bias_snapshots (id text primary key, asset_id text not null references assets(id) on delete cascade, direction text not null, score numeric(12,4) not null, confidence numeric(12,4) not null, change_1d numeric(12,4) not null, change_5d numeric(12,4) not null, created_at timestamptz not null default now());
create table if not exists market_bias_rationales (id text primary key, snapshot_id text not null references market_bias_snapshots(id) on delete cascade, rationale text not null);
create table if not exists briefings (id text primary key, slug text not null unique, kind text not null, title text not null, summary text not null, body text not null, analyst_user_id text not null references users(id), published_at timestamptz not null, event_id text references events(id), asset_symbols jsonb not null default '[]'::jsonb, takeaways jsonb not null default '[]'::jsonb);
create table if not exists news_items (id text primary key, slug text not null unique, title text not null, source text not null, summary text not null, category text not null, sentiment text not null, published_at timestamptz not null, event_id text references events(id));
create table if not exists watchlists (id text primary key, user_id text not null references users(id) on delete cascade, name text not null, description text not null default '', created_at timestamptz not null default now());
create table if not exists watchlist_items (id text primary key, watchlist_id text not null references watchlists(id) on delete cascade, item_type text not null, symbol text not null, note text not null default '');
create table if not exists alerts (id text primary key, user_id text not null references users(id) on delete cascade, name text not null, trigger_type text not null, target_ref text not null, threshold_value text not null, delivery_channel text not null, status text not null, last_triggered_at timestamptz, created_at timestamptz not null default now());
create table if not exists alert_deliveries (id text primary key, alert_id text not null references alerts(id) on delete cascade, status text not null, delivered_at timestamptz not null default now(), payload jsonb not null default '{}'::jsonb);
create table if not exists posts (id text primary key, user_id text not null references users(id) on delete cascade, title text not null, body text not null, created_at timestamptz not null default now(), moderated boolean not null default false);
create table if not exists comments (id text primary key, post_id text not null references posts(id) on delete cascade, user_id text not null references users(id) on delete cascade, body text not null, created_at timestamptz not null default now());
create table if not exists post_likes (post_id text not null references posts(id) on delete cascade, user_id text not null references users(id) on delete cascade, created_at timestamptz not null default now(), primary key (post_id, user_id));
create table if not exists feature_flags (key text primary key, description text not null, enabled boolean not null default false);
create table if not exists audit_logs (id text primary key, actor_user_id text references users(id), action text not null, entity_type text not null, entity_id text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists ingestion_jobs (id text primary key, job_type text not null, status text not null, payload jsonb not null default '{}'::jsonb, run_at timestamptz not null default now(), started_at timestamptz, finished_at timestamptz, error_message text, created_at timestamptz not null default now());
create index if not exists idx_events_scheduled_at on events(scheduled_at);
create index if not exists idx_sessions_user_id on sessions(user_id);
create index if not exists idx_jobs_status_run_at on ingestion_jobs(status, run_at);
create index if not exists idx_alerts_user_id on alerts(user_id);
